SELECT a.id, a.status, a.opened_date, t.lazada_count, t.starbucks_count FROM accounts a LEFT OUTER JOIN (SELECT account_id, SUM(CASE WHEN merchant = 'Lazada' THEN 1 ELSE 0 END) AS lazada_count, COUNT(CASE WHEN merchant = 'Starbucks' THEN 1 END) AS starbucks_count FROM transactions WHERE is_flagged GROUP BY account_id) t ON a.id = t.account_id WHERE t.lazada_count >= 46 ORDER BY a.id, starbucks_count DESC;
